@Composable fun KingZuluApp(){val context=androidx.compose.ui.platform.LocalContext.current;val prefs=remember{context.getSharedPreferences("king_zulu_presentation",android.content.Context.MODE_PRIVATE)};var tab by rememberSaveable{mutableStateOf("Bible")};var previewReference by rememberSaveable{mutableStateOf("")};var previewText by rememberSaveable{mutableStateOf("")};var previewTranslation by rememberSaveable{mutableStateOf("")};var previewKind by rememberSaveable{mutableStateOf("")};var presentation by remember{mutableStateOf(PreviewLiveState())};var theme by remember{mutableStateOf(LocalBackgroundStore.loadSelected(context))};var textSize by rememberSaveable{mutableIntStateOf(prefs.getInt("text_size",32))};var autoFit by rememberSaveable{mutableStateOf(prefs.getBoolean("auto_fit",true))};val preview=if(previewKind.isBlank())null else PresentationSlide(previewReference,previewText,previewTranslation,previewKind);val live=presentation.live.slide;fun setPreview(s:PresentationSlide?){previewReference=s?.reference.orEmpty();previewText=s?.text.orEmpty();previewTranslation=s?.translation.orEmpty();previewKind=s?.kind.orEmpty();if(s!=null)presentation=presentation.preview(s)};fun setLive(s:PresentationSlide?){presentation=presentation.present(s)};fun saveTextSettings(){prefs.edit().putInt("text_size",textSize).putBoolean("auto_fit",autoFit).apply()};val gallery=rememberLauncherForActivityResult(ActivityResultContracts.GetContent()){uri->uri?.let{theme=LocalBackgroundStore.importFromGallery(context,it)}};Scaffold(containerColor=KZBlack,topBar={Surface(color=KZBlack){Column{Row(Modifier.fillMaxWidth().padding(horizontal=18.dp,vertical=12.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("KING ZULU",fontWeight=FontWeight.Black,fontSize=22.sp);Text("Worship presentation",color=KZMuted,fontSize=12.sp)};Spacer(Modifier.weight(.1f));Surface(color=if(live!=null||presentation.live.black)Color(0xFF35161B)else KZSurface2,shape=RoundedCornerShape(999.dp)){Text(if(live!=null||presentation.live.black)"● LIVE" else "○ READY",Modifier.padding(horizontal=12.dp,vertical=8.dp),color=if(live!=null||presentation.live.black)KZLive else Color(0xFFB8BAC1),fontWeight=FontWeight.Black,fontSize=11.sp)}}}}},bottomBar={NavigationBar(containerColor=Color(0xFF101013)){listOf("Bible" to "B","Listen" to "L","Service" to "S","Media" to "M","Present" to "P").forEach{(item,glyph)->NavigationBarItem(selected=tab==item,onClick={tab=item},icon={Text(glyph,fontWeight=FontWeight.Bold)},label={Text(item,fontSize=10.sp)})}}}){pad->Column(Modifier.padding(pad).fillMaxSize().verticalScroll(rememberScrollState()).padding(18.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){when(tab){"Bible"->BiblePanel({setPreview(it);tab="Present"},{tab="Translations"});"Translations"->BibleTranslationsPanel{tab="Bible"};"Listen"->AiListenPanel({setPreview(it);tab="Present"},{s->setPreview(s);setLive(s);tab="Present"});"Service"->ServicePanel(preview,{setPreview(it);tab="Present"},{s->setPreview(s);setLive(s);tab="Present"});"Media"->MediaPanel({setPreview(it);tab="Present"},{s->setPreview(s);setLive(s)});else->LivePanel(preview,live,presentation.live.black,presentation.history.isNotEmpty(),theme,textSize,autoFit,{v->textSize=v;saveTextSettings()},{v->autoFit=v;prefs.edit().putBoolean("auto_fit",v).apply()},{setLive(it)},{presentation=presentation.black()},{presentation=presentation.previous()},{gallery.launch("image/*")})}}}}
