@Composable fun BiblePanel(onPreview:(PresentationSlide)->Unit,onTranslations:()->Unit){var q by rememberSaveable{mutableStateOf("")};var message by rememberSaveable{mutableStateOf("")};var translation by remember{mutableStateOf(OfflineBibleRepository.selectedTranslation())};val keyboard=LocalSoftwareKeyboardController.current;fun submit(){val r=BibleReferenceParser.parse(q);val v=r?.let{OfflineBibleRepository.get(it)};if(v!=null){message="";keyboard?.hide();onPreview(PresentationSlide(v.reference.display(),v.text,v.translation))}else message="Verse not found in $translation — check the reference"};val suggestions=remember(q){if(q.any{it.isDigit()})emptyList()else BibleReferenceParser.suggestions(q)};PageHeading("Bible","Find Scripture fast and prepare it for the congregation screen.");SectionCard{Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("ACTIVE TRANSLATION",fontSize=11.sp,fontWeight=FontWeight.Black,color=KZMuted);Text(translation,fontSize=22.sp,fontWeight=FontWeight.Black)};OutlinedButton({onTranslations()}){Text("TRANSLATIONS")}};OutlinedTextField(q,{q=it;message=""},Modifier.fillMaxWidth(),singleLine=true,label={Text("Reference")},placeholder={Text("Jn 5 24 • Rom 8 28")},keyboardOptions=KeyboardOptions(imeAction=ImeAction.Search),keyboardActions=KeyboardActions(onSearch={submit()}));if(suggestions.isNotEmpty())Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(6.dp)){suggestions.take(3).forEach{book->AssistChip(onClick={q="$book "},label={Text(book,maxLines=1)})}};Button({submit()},Modifier.fillMaxWidth()){Text("PREVIEW $translation VERSE")};if(message.isNotBlank())Text(message,color=KZPurpleSoft)}}
