@Composable private fun LyricsEditor(onPreview:(PresentationSlide)->Unit){var text by rememberSaveable{mutableStateOf("")};SectionCard{OutlinedTextField(text,{text=it},Modifier.fillMaxWidth().height(220.dp),label={Text("Paste or type lyrics")});Button({if(text.isNotBlank())onPreview(PresentationSlide(text=text.lines().take(4).joinToString("\n"),kind="lyrics"))},Modifier.fillMaxWidth()){Text("PREVIEW LYRICS")}}}
@Composable private fun TimerEditor(onPreview:(PresentationSlide)->Unit,onGoLive:(PresentationSlide)->Unit){val remaining=CountdownStore.remainingSeconds;val running=CountdownStore.running;val configured=CountdownStore.configuredMinutes;SectionCard{Text(CountdownStore.display(),fontSize=46.sp,fontWeight=FontWeight.Black);Text(if(running)"Countdown continues while you use Bible, Listen, Service or Present." else "Timer stays available across every page.",fontSize=12.sp,color=KZMuted);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton({CountdownStore.setMinutes(configured-1L)},enabled=!running,modifier=Modifier.weight(1f)){Text("−1 MIN")};OutlinedButton({CountdownStore.setMinutes(configured+1L)},enabled=!running,modifier=Modifier.weight(1f)){Text("+1 MIN")}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button({if(running)CountdownStore.pause() else CountdownStore.startOrResume();onGoLive(CountdownStore.slide())},Modifier.weight(1f)){Text(if(running)"PAUSE" else if(remaining<configured*60L)"RESUME" else "START")};OutlinedButton({CountdownStore.reset();onPreview(CountdownStore.slide())},Modifier.weight(1f)){Text("RESET")}};OutlinedButton({onPreview(CountdownStore.slide())},Modifier.fillMaxWidth()){Text("PREVIEW COUNTDOWN")}}}
@Composable fun LivePanel(preview:PresentationSlide?,live:PresentationSlide?,isBlack:Boolean,canPrevious:Boolean,theme:BackgroundTheme?,textSize:Int,autoFit:Boolean,onTextSize:(Int)->Unit,onAutoFit:(Boolean)->Unit,setLive:(PresentationSlide?)->Unit,black:()->Unit,previous:()->Unit,chooseBackground:()->Unit){PageHeading("Present","Preview first, then send confidently to the congregation display.");Text("PREVIEW",color=KZMuted);Surface(shape=RoundedCornerShape(20.dp),color=Color.Black){PresentationCanvas(preview,theme,Modifier.fillMaxWidth(),textSize,autoFit)};Button({setLive(preview)},enabled=preview!=null,modifier=Modifier.fillMaxWidth()){Text("GO LIVE")};SectionCard{Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.SpaceBetween){Text("TEXT SIZE",fontWeight=FontWeight.Bold);Row(verticalAlignment=Alignment.CenterVertically){OutlinedButton({onTextSize((textSize-2).coerceAtLeast(14))}){Text("−")};Text(" $textSize ",fontWeight=FontWeight.Bold);OutlinedButton({onTextSize((textSize+2).coerceAtMost(60))}){Text("+")}}};Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.SpaceBetween){Column{Text("AUTO FIT",fontWeight=FontWeight.Bold);Text("Shrink long passages automatically",fontSize=11.sp,color=KZMuted)};Switch(autoFit,onAutoFit)}};Text("CURRENT LIVE",color=KZMuted);Surface(shape=RoundedCornerShape(20.dp),color=Color.Black){if(isBlack)Box(Modifier.fillMaxWidth().height(210.dp))else PresentationCanvas(live,theme,Modifier.fillMaxWidth(),textSize,autoFit)};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){Button(black,Modifier.weight(1f)){Text("BLACK")};OutlinedButton({setLive(null)},Modifier.weight(1f)){Text("CLEAR")};OutlinedButton({setLive(PresentationSlide(text="KING ZULU",kind="logo"))},Modifier.weight(1f)){Text("LOGO")}};OutlinedButton(previous,enabled=canPrevious,modifier=Modifier.fillMaxWidth()){Text("↶ RESTORE PREVIOUS LIVE")};OutlinedButton(chooseBackground,Modifier.fillMaxWidth()){Text("BACKGROUND FROM GALLERY")}}
